#!/usr/bin/env bash
#
# sdk - switches between installed JDKs, per session.
#
# Requires bash 3.2+ (the native macOS version). Works on Linux, macOS, and
# Windows (Git Bash/MINGW64), with integration for bash and zsh through the
# helper generated by `sdk install`.
#
# The list lives in ~/.config/sdk/sdk.conf, in the format name=path.
# The first valid entry is the default applied to each new shell.

# ---------------------------------------------------------------------------
# Compatibility
# ---------------------------------------------------------------------------

if [ -z "${BASH_VERSION:-}" ]; then
  if command -v bash >/dev/null 2>&1; then
    exec bash "$0" "$@"
  fi
  printf 'sdk: error: requires bash 3.2 or higher\n' >&2
  exit 1
fi

if [ "${BASH_VERSINFO[0]:-0}" -lt 3 ] ||
   { [ "${BASH_VERSINFO[0]}" -eq 3 ] && [ "${BASH_VERSINFO[1]:-0}" -lt 2 ]; }; then
  printf 'sdk: error: requires bash 3.2 or higher\n' >&2
  exit 1
fi

PROG=sdk
HOME_DIR=${HOME:?}
CONF_DIR=$HOME_DIR/.config/sdk
CONF_FILE=$CONF_DIR/sdk.conf
HELPER_FILE=$CONF_DIR/sdk.sh
BIN_DIR=$HOME_DIR/.local/bin
BIN_FILE=$BIN_DIR/sdk

# Internal mode: prints only shell code to stdout.
EMIT=0
QUIET=0

# Loaded list state.
CONF_NAMES=()
CONF_PATHS=()
CONF_PROBLEMS=()

# Uninstall state.
UN_RC_FILES=()
UN_TMP_FILES=()
UN_CHANGES=0

# ---------------------------------------------------------------------------
# Messages
# ---------------------------------------------------------------------------

msg() {
  [ "$QUIET" -eq 1 ] && return 0
  printf '%s\n' "$*" >&2
}

warn() {
  [ "$QUIET" -eq 1 ] && return 0
  printf 'sdk: warning: %s\n' "$*" >&2
}

error() {
  printf 'sdk: error: %s\n' "$*" >&2
}

usage() {
  cat <<'EOF'
sdk - switches JDK versions in the current session

Usage:
  sdk                      interactive menu
  sdk list                 lists the configured JDKs
  sdk use <name>           activates the given JDK in this session
  sdk current              shows the active JDK
  sdk reset                goes back to the first valid entry
  sdk install [--shell S]  installs/updates (S = bash|zsh)
  sdk uninstall            removes the integration and configuration
  sdk help                 this help

Configuration: ~/.config/sdk/sdk.conf
  # name=path
  jdk21=/opt/jdk-21
The first valid entry is the default applied to each new shell.

Switching affects only the current session. Use the function installed in the
rc files or: eval "$(sdk --emit use <name>)".

Internal options: --emit (shell code to stdout) and --quiet.
EOF
}

# ---------------------------------------------------------------------------
# Portable utilities (no GNU-only / BSD-only)
# ---------------------------------------------------------------------------

trim() {
  local s=$1
  while :; do
    case $s in
      ' '*)   s=${s# } ;;
      $'\t'*) s=${s#$'\t'} ;;
      *)      break ;;
    esac
  done
  while :; do
    case $s in
      *' ')   s=${s% } ;;
      *$'\t') s=${s%$'\t'} ;;
      *)      break ;;
    esac
  done
  printf '%s' "$s"
}

# Resolves symlinks and directories containing .. without relying on `readlink -f`.
resolve_path() {
  local p=$1 d b

  [ -n "$p" ] || return 1
  [ "$p" = "/" ] && { printf '/'; return 0; }

  while [ "${p%/}" != "$p" ] && [ "$p" != "/" ]; do
    p=${p%/}
  done

  while [ -L "$p" ]; do
    d=${p%/*}
    [ "$d" = "$p" ] && d=.
    b=$(readlink "$p" 2>/dev/null) || return 1
    [ -n "$b" ] || return 1
    case $b in
      /*) p=$b ;;
      *)  p=$d/$b ;;
    esac
    while [ "${p%/}" != "$p" ] && [ "$p" != "/" ]; do
      p=${p%/}
    done
  done

  d=${p%/*}
  [ "$d" = "$p" ] && d=.
  b=${p##*/}

  if d=$(cd -P "$d" 2>/dev/null && pwd -P); then
    printf '%s/%s\n' "$d" "$b"
  else
    return 1
  fi
}

# Safe single quotes for the emitted code.
shell_quote() {
  local s=$1 out
  case $s in
    *\'*)
      out="'"
      while :; do
        case $s in
          *\'*)
            out="$out${s%%\'*}'\''"
            s=${s#*\'}
            ;;
          *)
            out="$out$s'"
            break
            ;;
        esac
      done
      printf '%s' "$out"
      ;;
    *)
      printf "'%s'" "$s"
      ;;
  esac
}

is_mingw() {
  local os
  os=$(uname -s 2>/dev/null) || os=
  case $os in
    MINGW*) return 0 ;;
  esac
  case ${OSTYPE:-} in
    mingw*) return 0 ;;
  esac
  return 1
}

# Converts Windows drive paths (C:\... or C:/...) to the POSIX form used by
# Git Bash (/c/...). Other paths are returned unchanged.
to_posix_path() {
  local p=$1 drive rest out
  if ! is_mingw; then
    printf '%s' "$p"
    return 0
  fi
  case $p in
    [A-Za-z]:[\\/]*)
      if command -v cygpath >/dev/null 2>&1; then
        out=$(cygpath -u "$p" 2>/dev/null) || out=
        if [ -n "$out" ]; then
          printf '%s' "$out"
          return 0
        fi
      fi
      drive=$(printf '%s' "${p%%:*}" | tr 'A-Z' 'a-z')
      rest=${p#?:}
      rest=${rest//\\//}
      printf '/%s%s' "$drive" "$rest"
      ;;
    *)
      printf '%s' "$p"
      ;;
  esac
}

detect_os() {
  local os
  os=$(uname -s 2>/dev/null) || os=
  case $os in
    MINGW*)  printf 'MINGW'; return 0 ;;
    Darwin*) printf 'Darwin'; return 0 ;;
    Linux*)  printf 'Linux'; return 0 ;;
  esac
  case ${OSTYPE:-} in
    mingw*)  printf 'MINGW' ;;
    darwin*) printf 'Darwin' ;;
    linux*)  printf 'Linux' ;;
    *)       printf 'Unknown' ;;
  esac
}

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------

load_conf() {
  CONF_NAMES=()
  CONF_PATHS=()
  CONF_PROBLEMS=()

  if [ ! -e "$CONF_FILE" ]; then
    error "configuration file not found: $CONF_FILE"
    error "run 'sdk install' to create it"
    return 1
  fi
  if [ ! -f "$CONF_FILE" ]; then
    error "$CONF_FILE exists, but is not a regular file"
    return 1
  fi
  if [ ! -r "$CONF_FILE" ]; then
    error "no read permission: $CONF_FILE"
    return 1
  fi

  local n=0 line name path i dup
  while IFS= read -r line || [ -n "$line" ]; do
    n=$((n + 1))
    line=${line%$'\r'}
    line=$(trim "$line")

    [ -z "$line" ] && continue
    case $line in
      '#'*) continue ;;
    esac

    case $line in
      *=*) ;;
      *)
        CONF_PROBLEMS+=("line $n: missing '='")
        continue
        ;;
    esac

    name=${line%%=*}
    path=${line#*=}
    name=$(trim "$name")
    path=$(trim "$path")

    if [ -z "$name" ] || [ -z "$path" ]; then
      CONF_PROBLEMS+=("line $n: empty name or path")
      continue
    fi

    case $name in
      *[!A-Za-z0-9._-]*)
        CONF_PROBLEMS+=("line $n: invalid name '$name'")
        continue
        ;;
    esac

    case $path in
      '~')   path=$HOME_DIR ;;
      '~/'*) path=$HOME_DIR/${path#\~/} ;;
    esac
    path=$(to_posix_path "$path")

    case $path in
      /*) ;;
      *)
        CONF_PROBLEMS+=("line $n: non-absolute path '$path'")
        continue
        ;;
    esac

    dup=0
    i=0
    while [ "$i" -lt "${#CONF_NAMES[@]}" ]; do
      if [ "${CONF_NAMES[$i]}" = "$name" ]; then
        dup=1
        break
      fi
      i=$((i + 1))
    done
    if [ "$dup" -eq 1 ]; then
      CONF_PROBLEMS+=("line $n: duplicate name '$name'")
      continue
    fi

    CONF_NAMES+=("$name")
    CONF_PATHS+=("$path")
  done < "$CONF_FILE"

  if [ "${#CONF_NAMES[@]}" -eq 0 ]; then
    error "no JDK declared in $CONF_FILE"
    return 1
  fi
  return 0
}

show_problems() {
  local p
  for p in "${CONF_PROBLEMS[@]}"; do
    [ -n "$p" ] && warn "$p"
  done
}

entry_valid() {
  local p=${CONF_PATHS[$1]}
  [ -n "$p" ] && [ -d "$p" ] || return 1
  if is_mingw && [ -f "$p/bin/java.exe" ]; then
    return 0
  fi
  [ -f "$p/bin/java" ] && [ -x "$p/bin/java" ]
}

entry_version() {
  local p=${CONF_PATHS[$1]} line v
  [ -f "$p/release" ] || return 0
  while IFS= read -r line || [ -n "$line" ]; do
    line=${line%$'\r'}
    case $line in
      JAVA_VERSION=*)
        v=${line#JAVA_VERSION=}
        v=${v%\"}
        v=${v#\"}
        printf '%s' "$v"
        return 0
        ;;
    esac
  done < "$p/release"
  return 0
}

first_valid() {
  local i=0
  while [ "$i" -lt "${#CONF_PATHS[@]}" ]; do
    if entry_valid "$i"; then
      printf '%s' "$i"
      return 0
    fi
    i=$((i + 1))
  done
  return 1
}

find_name() {
  local i=0
  while [ "$i" -lt "${#CONF_NAMES[@]}" ]; do
    if [ "${CONF_NAMES[$i]}" = "$1" ]; then
      printf '%s' "$i"
      return 0
    fi
    i=$((i + 1))
  done
  return 1
}

active_index() {
  local jh=${JAVA_HOME:-} rp i ep
  [ -n "$jh" ] || return 1
  jh=$(to_posix_path "$jh")
  rp=$(resolve_path "$jh") || rp=$jh
  i=0
  while [ "$i" -lt "${#CONF_PATHS[@]}" ]; do
    ep=$(resolve_path "${CONF_PATHS[$i]}") || ep=${CONF_PATHS[$i]}
    if [ "$rp" = "$ep" ]; then
      printf '%s' "$i"
      return 0
    fi
    i=$((i + 1))
  done
  return 1
}

# ---------------------------------------------------------------------------
# Environment emission
# ---------------------------------------------------------------------------

emit_env() {
  local idx=$1
  local path=${CONF_PATHS[$idx]}
  local newbin=$path/bin
  local oldbin=
  local newpath rest p skip j jb

  if [ -n "${JAVA_HOME:-}" ]; then
    oldbin=$(to_posix_path "$JAVA_HOME")/bin
  fi

  newpath=$newbin
  rest=${PATH:-}
  while [ -n "$rest" ]; do
    p=${rest%%:*}
    case $rest in
      *:*) rest=${rest#*:} ;;
      *)   rest= ;;
    esac
    [ -z "$p" ] && continue

    skip=0
    [ "$p" = "$newbin" ] && skip=1
    if [ "$skip" -eq 0 ] && [ -n "$oldbin" ] && [ "$p" = "$oldbin" ]; then
      skip=1
    fi
    if [ "$skip" -eq 0 ]; then
      j=0
      while [ "$j" -lt "${#CONF_PATHS[@]}" ]; do
        jb=${CONF_PATHS[$j]}/bin
        if [ "$p" = "$jb" ]; then
          skip=1
          break
        fi
        j=$((j + 1))
      done
    fi
    [ "$skip" -eq 0 ] && newpath="$newpath:$p"
  done

  printf 'export JAVA_HOME=%s\n' "$(shell_quote "$path")"
  printf 'export PATH=%s\n' "$(shell_quote "$newpath")"
}

# ---------------------------------------------------------------------------
# Commands
# ---------------------------------------------------------------------------

cmd_list() {
  load_conf || return 1
  show_problems

  local def active i act defm ver suffix
  def=$(first_valid) || def=
  active=$(active_index) || active=

  printf '%-2s %-2s %-14s %-14s %s\n' '' '' 'NAME' 'VERSION' 'PATH'
  i=0
  while [ "$i" -lt "${#CONF_NAMES[@]}" ]; do
    if [ -n "$active" ] && [ "$active" = "$i" ]; then act='*'; else act=' '; fi
    if [ -n "$def" ] && [ "$def" = "$i" ]; then defm='d'; else defm=' '; fi
    ver=$(entry_version "$i")
    [ -n "$ver" ] || ver='?'
    if entry_valid "$i"; then suffix=''; else suffix='  [invalid]'; fi

    printf '%-2s %-2s %-14s %-14s %s%s\n' \
      "$act" "$defm" "${CONF_NAMES[$i]}" "$ver" "${CONF_PATHS[$i]}" "$suffix"
    i=$((i + 1))
  done

  if [ -z "$active" ]; then
    printf '\nNo listed JDK is active in this session.\n'
  fi
  return 0
}

cmd_current() {
  load_conf || return 1

  local i java
  i=$(active_index) || i=
  if [ -n "$i" ]; then
    printf 'Name: %s\n' "${CONF_NAMES[$i]}"
    printf 'Version: %s\n' "$(entry_version "$i")"
    printf 'JAVA_HOME: %s\n' "${CONF_PATHS[$i]}"
  elif [ -n "${JAVA_HOME:-}" ]; then
    printf 'JAVA_HOME: %s (not in the list)\n' "$JAVA_HOME"
  else
    printf 'No active JDK (JAVA_HOME not set).\n'
  fi

  java=$(command -v java 2>/dev/null) || java=
  [ -n "$java" ] && printf 'java: %s\n' "$java"
  return 0
}

cmd_use() {
  local name=$1 idx ver

  if [ -z "$name" ]; then
    interactive_menu
    return $?
  fi

  load_conf || return 1

  idx=$(find_name "$name") || {
    error "JDK '$name' not found in $CONF_FILE"
    printf 'Available: %s\n' "${CONF_NAMES[*]}" >&2
    return 1
  }

  if ! entry_valid "$idx"; then
    error "JDK '$name' is invalid: ${CONF_PATHS[$idx]}/bin/java not found or not executable"
    return 1
  fi

  emit_env "$idx"
  ver=$(entry_version "$idx")
  [ -n "$ver" ] || ver='unknown version'
  msg "JDK active: ${CONF_NAMES[$idx]} ($ver)"
}

cmd_reset() {
  local idx ver
  load_conf || return 1

  idx=$(first_valid) || {
    error "no valid JDK found in $CONF_FILE"
    return 1
  }

  emit_env "$idx"
  ver=$(entry_version "$idx")
  [ -n "$ver" ] || ver='unknown version'
  msg "JDK default: ${CONF_NAMES[$idx]} ($ver)"
}

interactive_menu() {
  load_conf || return 1
  show_problems

  local def active i choice idx ver mark dmark menu_in=0 menu_out=2
  def=$(first_valid) || def=
  active=$(active_index) || active=

  if exec 3<>/dev/tty 2>/dev/null; then
    menu_in=3
    menu_out=3
  fi

  printf 'Available JDKs:\n' >&$menu_out
  i=0
  while [ "$i" -lt "${#CONF_NAMES[@]}" ]; do
    mark=' '
    dmark=' '
    [ -n "$active" ] && [ "$active" = "$i" ] && mark='*'
    [ -n "$def" ] && [ "$def" = "$i" ] && dmark='d'
    ver=$(entry_version "$i")
    [ -n "$ver" ] || ver='?'

    if entry_valid "$i"; then
      printf '  %2d) [%s%s] %s (%s)\n' \
        $((i + 1)) "$mark" "$dmark" "${CONF_NAMES[$i]}" "$ver" >&$menu_out
    else
      printf '  %2d) [%s%s] %s (%s) [invalid]\n' \
        $((i + 1)) "$mark" "$dmark" "${CONF_NAMES[$i]}" "$ver" >&$menu_out
    fi
    i=$((i + 1))
  done

  printf 'Choice (1-%d, Enter cancels): ' "${#CONF_NAMES[@]}" >&$menu_out
  choice=
  IFS= read -r choice <&$menu_in
  if [ "$menu_in" -eq 3 ]; then
    exec 3>&-
  fi

  case $choice in
    ''|q|Q)
      msg 'cancelled'
      return 0
      ;;
  esac

  case $choice in
    *[!0-9]*)
      error "invalid option: $choice"
      return 1
      ;;
  esac

  idx=$((choice - 1))
  if [ "$idx" -lt 0 ] || [ "$idx" -ge "${#CONF_NAMES[@]}" ]; then
    error "option out of range: $choice"
    return 1
  fi
  if ! entry_valid "$idx"; then
    error "JDK '${CONF_NAMES[$idx]}' is invalid"
    return 1
  fi

  emit_env "$idx"
  ver=$(entry_version "$idx")
  [ -n "$ver" ] || ver='unknown version'
  msg "JDK active: ${CONF_NAMES[$idx]} ($ver)"
}

# ---------------------------------------------------------------------------
# Installation
# ---------------------------------------------------------------------------

normalize_shell_name() {
  local p=$1
  p=${p##*/}
  p=${p#-}
  p=${p%.exe}
  printf '%s' "$p" | tr 'A-Z' 'a-z'
}

detect_shell() {
  local forced=${1:-} p

  case $forced in
    '') ;;
    bash|zsh)
      printf '%s' "$forced"
      return 0
      ;;
    *)
      error "invalid shell: $forced (use bash or zsh)"
      return 1
      ;;
  esac

  case ${SDK_CALLER_SHELL:-} in
    bash|zsh)
      printf '%s' "$SDK_CALLER_SHELL"
      return 0
      ;;
  esac

  p=$(normalize_shell_name "$(ps -p "$PPID" -o comm= 2>/dev/null)")
  case $p in
    bash|zsh)
      printf '%s' "$p"
      return 0
      ;;
  esac

  p=$(normalize_shell_name "${SHELL:-}")
  case $p in
    bash|zsh)
      printf '%s' "$p"
      return 0
      ;;
  esac

  return 1
}

script_source() {
  local src=${BASH_SOURCE[0]:-$0} found
  if [ ! -f "$src" ]; then
    found=$(command -v "$src" 2>/dev/null) || found=
    [ -n "$found" ] && src=$found
  fi
  resolve_path "$src" || printf '%s' "$src"
}

create_template() {
  local tmp=$CONF_FILE.tmp.$$
  {
    printf '%s\n' '# JDK list: name=path'
    printf '%s\n' '# The first valid entry is the default (applied to every new shell).'
    printf '%s\n' '# Example:'
    printf '%s\n' '# jdk21=/opt/jdk-21'
  } > "$tmp" 2>/dev/null || {
    rm -f "$tmp"
    return 1
  }
  mv -f "$tmp" "$CONF_FILE" 2>/dev/null || {
    rm -f "$tmp"
    return 1
  }
  return 0
}

copy_self() {
  local src dst tmp rs rd

  src=$(script_source)
  dst=$BIN_FILE

  if [ -d "$dst" ]; then
    error "$dst is a directory; remove it before installing"
    return 1
  fi

  if [ -n "$src" ] && [ -e "$dst" ]; then
    rs=$(resolve_path "$src") || rs=$src
    rd=$(resolve_path "$dst") || rd=$dst
    if [ "$rs" = "$rd" ]; then
      msg "binary is already at $BIN_FILE"
      return 0
    fi
  fi

  tmp=$dst.tmp.$$
  rm -f "$tmp"
  if ! cp "$src" "$tmp" 2>/dev/null; then
    rm -f "$tmp"
    error "failed to copy $src to $tmp"
    return 1
  fi
  if ! chmod 755 "$tmp" 2>/dev/null; then
    rm -f "$tmp"
    error "failed to set permissions on $tmp"
    return 1
  fi
  if ! mv -f "$tmp" "$dst" 2>/dev/null; then
    rm -f "$tmp"
    error "failed to move $tmp to $dst"
    return 1
  fi

  msg "binary installed: $BIN_FILE"
  return 0
}

write_helper() {
  local tmp=$HELPER_FILE.tmp.$$

  rm -f "$tmp"
  if ! cat > "$tmp" <<'JDK_HELPER_EOF'
# sdk helper, generated by `sdk install`. Loaded by the rc files.
if [ -n "${_SDK_HELPER_LOADED:-}" ]; then return 0; fi
_SDK_HELPER_LOADED=1

sdk() {
  local _out _shell=bash
  [ -n "${ZSH_VERSION:-}" ] && _shell=zsh
  case "${1:-}" in
    install)
      SDK_CALLER_SHELL=$_shell command sdk "$@"
      ;;
    use|reset|"")
      _out=$(command sdk --emit "$@") || return $?
      eval "$_out"
      ;;
    *)
      command sdk "$@"
      ;;
  esac
}

eval "$(command sdk --emit --quiet reset 2>/dev/null)"
JDK_HELPER_EOF
  then
    rm -f "$tmp"
    error "failed to write $HELPER_FILE"
    return 1
  fi

  chmod 644 "$tmp" 2>/dev/null || true
  if ! mv -f "$tmp" "$HELPER_FILE" 2>/dev/null; then
    rm -f "$tmp"
    error "failed to install $HELPER_FILE"
    return 1
  fi

  msg "helper installed: $HELPER_FILE"
  return 0
}

update_rc() {
  local shell=$1 os f tmp line norm eol first in_block
  local rc_files
  rc_files=()

  os=$(detect_os)
  case $shell in
    bash)
      case $os in
        Darwin|MINGW)
          rc_files+=("$HOME_DIR/.bash_profile")
          [ -f "$HOME_DIR/.bashrc" ] && rc_files+=("$HOME_DIR/.bashrc")
          ;;
        *)
          rc_files+=("$HOME_DIR/.bashrc")
          ;;
      esac
      ;;
    zsh)
      rc_files+=("$HOME_DIR/.zshrc")
      ;;
    *)
      error "unsupported shell: $shell"
      return 1
      ;;
  esac

  for f in "${rc_files[@]}"; do
    if [ -e "$f" ] && [ ! -f "$f" ]; then
      warn "$f is not a regular file; skipping"
      continue
    fi
    if [ ! -e "$f" ]; then
      if ! printf '' >> "$f" 2>/dev/null; then
        error "could not create $f"
        continue
      fi
    fi

    eol='\n'
    if [ -s "$f" ]; then
      first=
      IFS= read -r first < "$f" || true
      case $first in
        *$'\r') eol='\r\n' ;;
      esac
    elif [ "$os" = MINGW ]; then
      eol='\r\n'
    fi

    tmp=$f.tmp.$$
    rm -f "$tmp"
    in_block=0
    while IFS= read -r line || [ -n "$line" ]; do
      norm=${line%$'\r'}
      case $norm in
        '# >>> sdk >>>')
          in_block=1
          continue
          ;;
        '# <<< sdk <<<')
          in_block=0
          continue
          ;;
      esac
      [ "$in_block" -eq 1 ] && continue
      printf '%s\n' "$line" >> "$tmp"
    done < "$f"

    {
      printf '%s%b' '# >>> sdk >>>' "$eol"
      printf '%s%b' '[ -r "$HOME/.config/sdk/sdk.sh" ] && . "$HOME/.config/sdk/sdk.sh"' "$eol"
      printf '%s%b' '# <<< sdk <<<' "$eol"
    } >> "$tmp"

    if cat "$tmp" > "$f" 2>/dev/null; then
      rm -f "$tmp"
      msg "rc updated: $f"
    else
      rm -f "$tmp"
      error "failed to update $f"
    fi
  done
  return 0
}

cmd_install() {
  local forced=$1 shell os rc

  shell=$(detect_shell "$forced") || {
    error "could not detect the shell; use: sdk install --shell bash|zsh"
    return 1
  }

  if ! mkdir -p "$CONF_DIR" "$BIN_DIR"; then
    error "could not create $CONF_DIR and/or $BIN_DIR"
    return 1
  fi

  if [ -f "$CONF_FILE" ]; then
    msg "configuration already exists, preserved: $CONF_FILE"
  elif [ -e "$CONF_FILE" ]; then
    error "$CONF_FILE exists, but is not a regular file"
    return 1
  else
    if ! create_template; then
      error "failed to create $CONF_FILE"
      return 1
    fi
    msg "configuration created: $CONF_FILE"
  fi

  copy_self || return 1
  write_helper || return 1
  update_rc "$shell" || return 1

  case :$PATH: in
    *:$BIN_DIR:*)
      ;;
    *)
      msg "warning: $BIN_DIR is not in PATH"
      msg "add to your profile: export PATH=\"\$HOME/.local/bin:\$PATH\""
      ;;
  esac

  os=$(detect_os)
  case $shell in
    zsh)
      rc=$HOME_DIR/.zshrc
      ;;
    bash)
      case $os in
        Darwin|MINGW) rc=$HOME_DIR/.bash_profile ;;
        *)            rc=$HOME_DIR/.bashrc ;;
      esac
      ;;
  esac

  msg "installation complete for $shell"
  msg "reload the session with: source $rc"
  return 0
}

# ---------------------------------------------------------------------------
# Uninstallation
# ---------------------------------------------------------------------------

uninstall_cleanup() {
  local t
  for t in "${UN_TMP_FILES[@]}"; do
    [ -n "$t" ] && rm -f "$t"
  done
  UN_TMP_FILES=()
}

# Scans one rc file, prints a before/after preview and, when a complete sdk
# block exists, stages the sanitized result in a temporary file.
preview_rc_file() {
  local f=$1
  local line norm rc n=0 state=0 open_line=0 i b s e cs ce shown
  local no_final_newline=0 tmp
  local -a lines keep starts ends
  lines=()
  keep=()
  starts=()
  ends=()

  while :; do
    IFS= read -r line
    rc=$?
    if [ "$rc" -ne 0 ] && [ -z "$line" ]; then
      break
    fi
    if [ "$rc" -ne 0 ]; then
      no_final_newline=1
    fi
    norm=${line%$'\r'}

    if [ "$norm" = '# >>> sdk >>>' ]; then
      if [ "$state" -eq 1 ]; then
        warn "$f has a nested '# >>> sdk >>>' at line $((n + 1)); this file will not be changed"
        return 0
      fi
      state=1
      open_line=$((n + 1))
      lines+=("$line")
      keep+=(0)
    elif [ "$norm" = '# <<< sdk <<<' ]; then
      if [ "$state" -eq 0 ]; then
        warn "$f has '# <<< sdk <<<' at line $((n + 1)) without '# >>> sdk >>>'; this file will not be changed"
        return 0
      fi
      state=0
      lines+=("$line")
      keep+=(0)
      starts+=($((open_line - 1)))
      ends+=("$n")
    else
      lines+=("$line")
      if [ "$state" -eq 1 ]; then
        keep+=(0)
      else
        keep+=(1)
      fi
    fi
    n=$((n + 1))
  done < "$f"

  if [ "$state" -eq 1 ]; then
    warn "$f has '# >>> sdk >>>' at line $open_line without '# <<< sdk <<<'; this file will not be changed"
    return 0
  fi
  if [ "${#starts[@]}" -eq 0 ]; then
    return 0
  fi

  tmp=$f.uninstall.$$
  rm -f "$tmp"
  : > "$tmp" 2>/dev/null || {
    error "failed to create $tmp"
    return 1
  }

  i=0
  while [ "$i" -lt "$n" ]; do
    if [ "${keep[$i]}" -eq 1 ]; then
      if [ "$i" -eq $((n - 1)) ] && [ "$no_final_newline" -eq 1 ]; then
        printf '%s' "${lines[$i]}" >> "$tmp"
      else
        printf '%s\n' "${lines[$i]}" >> "$tmp"
      fi
    fi
    i=$((i + 1))
  done

  UN_RC_FILES+=("$f")
  UN_TMP_FILES+=("$tmp")
  UN_CHANGES=$((UN_CHANGES + 1))

  msg "sdk: $f"
  b=0
  while [ "$b" -lt "${#starts[@]}" ]; do
    s=${starts[$b]}
    e=${ends[$b]}
    cs=$((s - 3))
    [ "$cs" -lt 0 ] && cs=0
    ce=$((e + 3))
    [ "$ce" -ge "$n" ] && ce=$((n - 1))

    msg "  before:"
    [ "$cs" -gt 0 ] && msg "    ..."
    i=$cs
    while [ "$i" -le "$ce" ]; do
      msg "    ${lines[$i]%$'\r'}"
      i=$((i + 1))
    done
    [ "$ce" -lt $((n - 1)) ] && msg "    ..."

    msg "  after:"
    [ "$cs" -gt 0 ] && msg "    ..."
    shown=0
    i=$cs
    while [ "$i" -le "$ce" ]; do
      if [ "${keep[$i]}" -eq 1 ]; then
        msg "    ${lines[$i]%$'\r'}"
        shown=1
      fi
      i=$((i + 1))
    done
    [ "$shown" -eq 0 ] && msg "    (empty file)"
    [ "$ce" -lt $((n - 1)) ] && msg "    ..."
    b=$((b + 1))
  done
  return 0
}

cmd_uninstall() {
  local f i helper_ok=0 conf_ok=0 bin_ok=0 dir_ok=0 fail=0 answer=
  local -a rc_candidates
  rc_candidates=("$HOME_DIR/.bashrc" "$HOME_DIR/.bash_profile" "$HOME_DIR/.zshrc")

  if [ $# -gt 0 ]; then
    error "unknown argument: $1"
    return 2
  fi

  UN_RC_FILES=()
  UN_TMP_FILES=()
  UN_CHANGES=0

  for f in "${rc_candidates[@]}"; do
    [ -e "$f" ] || continue
    if [ ! -f "$f" ]; then
      warn "$f is not a regular file; skipping"
      continue
    fi
    if [ ! -r "$f" ]; then
      warn "no read permission: $f; skipping"
      continue
    fi
    if [ ! -w "$f" ]; then
      warn "no write permission: $f; skipping"
      continue
    fi
    if ! preview_rc_file "$f"; then
      uninstall_cleanup
      return 1
    fi
  done

  if [ -e "$HELPER_FILE" ]; then
    if [ ! -f "$HELPER_FILE" ]; then
      warn "$HELPER_FILE is not a regular file; skipping"
    elif grep -q '_SDK_HELPER_LOADED' "$HELPER_FILE" 2>/dev/null; then
      helper_ok=1
    else
      warn "$HELPER_FILE does not look like the sdk helper; skipping"
    fi
  fi

  if [ -e "$CONF_FILE" ]; then
    if [ -f "$CONF_FILE" ]; then
      conf_ok=1
    else
      warn "$CONF_FILE is not a regular file; skipping"
    fi
  fi

  if [ -e "$BIN_FILE" ] || [ -L "$BIN_FILE" ]; then
    if [ -d "$BIN_FILE" ]; then
      error "$BIN_FILE is a directory; not removing"
      fail=1
    else
      bin_ok=1
    fi
  fi

  if [ -d "$CONF_DIR" ]; then
    dir_ok=1
  fi

  if [ "$UN_CHANGES" -eq 0 ] && [ "$helper_ok" -eq 0 ] &&
     [ "$conf_ok" -eq 0 ] && [ "$bin_ok" -eq 0 ] && [ "$dir_ok" -eq 0 ]; then
    msg "nothing to remove"
    uninstall_cleanup
    return "$fail"
  fi

  msg "sdk: the following will be removed:"
  i=0
  while [ "$i" -lt "${#UN_RC_FILES[@]}" ]; do
    msg "  - rc block: ${UN_RC_FILES[$i]}"
    i=$((i + 1))
  done
  [ "$helper_ok" -eq 1 ] && msg "  - helper: $HELPER_FILE"
  [ "$conf_ok" -eq 1 ] && msg "  - config: $CONF_FILE"
  [ "$dir_ok" -eq 1 ] && msg "  - directory: $CONF_DIR (only if empty)"
  [ "$bin_ok" -eq 1 ] && msg "  - binary: $BIN_FILE"

  printf 'Remove the items above? [y/N] ' >&2
  IFS= read -r answer || answer=
  [ -t 0 ] || printf '\n' >&2
  case $answer in
    y|Y) ;;
    *)
      uninstall_cleanup
      msg "cancelled"
      return 0
      ;;
  esac

  i=0
  while [ "$i" -lt "${#UN_RC_FILES[@]}" ]; do
    f=${UN_RC_FILES[$i]}
    if cat "${UN_TMP_FILES[$i]}" > "$f" 2>/dev/null; then
      msg "rc updated: $f"
    else
      error "failed to update $f"
      fail=1
    fi
    rm -f "${UN_TMP_FILES[$i]}"
    i=$((i + 1))
  done
  UN_TMP_FILES=()

  if [ "$helper_ok" -eq 1 ]; then
    if rm -f "$HELPER_FILE" 2>/dev/null; then
      msg "helper removed: $HELPER_FILE"
    else
      error "failed to remove $HELPER_FILE"
      fail=1
    fi
  fi

  if [ "$conf_ok" -eq 1 ]; then
    if rm -f "$CONF_FILE" 2>/dev/null; then
      msg "config removed: $CONF_FILE"
    else
      error "failed to remove $CONF_FILE"
      fail=1
    fi
  fi

  if [ "$dir_ok" -eq 1 ]; then
    if rmdir "$CONF_DIR" 2>/dev/null; then
      msg "directory removed: $CONF_DIR"
    else
      msg "directory kept (not empty): $CONF_DIR"
    fi
  fi

  if [ "$bin_ok" -eq 1 ]; then
    if rm -f "$BIN_FILE" 2>/dev/null; then
      msg "binary removed: $BIN_FILE"
    else
      error "failed to remove $BIN_FILE"
      fail=1
    fi
  fi

  if [ "$fail" -eq 0 ]; then
    msg "uninstall complete"
  else
    msg "uninstall finished with errors"
  fi
  msg "open a new shell (or run 'unset -f sdk') to drop the sdk function"
  msg "JAVA_HOME and PATH are not reverted in the current session"
  return "$fail"
}

# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------

main() {
  local cmd forced

  while [ $# -gt 0 ]; do
    case $1 in
      --emit)  EMIT=1; shift ;;
      --quiet) QUIET=1; shift ;;
      --)      shift; break ;;
      -h|--help)
        usage
        return 0
        ;;
      *)
        break
        ;;
    esac
  done

  cmd=${1:-}
  [ $# -gt 0 ] && shift

  if [ "$EMIT" -eq 0 ] && [ -t 1 ]; then
    case $cmd in
      use|reset|'')
        warn "to apply in this session use the installed function or: eval \"\$(sdk --emit $cmd)\""
        ;;
    esac
  fi

  case $cmd in
    '')
      interactive_menu
      ;;
    list)
      if [ "$EMIT" -eq 1 ]; then
        error "--emit does not apply to 'list'"
        return 2
      fi
      cmd_list
      ;;
    current)
      if [ "$EMIT" -eq 1 ]; then
        error "--emit does not apply to 'current'"
        return 2
      fi
      cmd_current
      ;;
    use)
      cmd_use "${1:-}"
      ;;
    reset)
      cmd_reset
      ;;
    install)
      if [ "$EMIT" -eq 1 ]; then
        error "--emit does not apply to 'install'"
        return 2
      fi
      forced=
      while [ $# -gt 0 ]; do
        case $1 in
          --shell)
            if [ $# -lt 2 ]; then
              error "--shell requires bash or zsh"
              return 2
            fi
            forced=$2
            shift 2
            ;;
          --shell=*)
            forced=${1#--shell=}
            shift
            ;;
          *)
            error "unknown argument: $1"
            return 2
            ;;
        esac
      done
      cmd_install "$forced"
      ;;
    uninstall)
      if [ "$EMIT" -eq 1 ]; then
        error "--emit does not apply to 'uninstall'"
        return 2
      fi
      cmd_uninstall "$@"
      ;;
    help)
      usage
      ;;
    *)
      error "unknown command: $cmd"
      usage >&2
      return 2
      ;;
  esac
}

main "$@"
exit $?
